//! Offline adoption of a verified pre-ADR-0090 default WAL.
//! Run the self-contained example: cargo run -p cypherlite --example adopt_legacy_wal
//! Adopt an operator-verified, closed store: cargo run -p cypherlite --example adopt_legacy_wal -- /path/to/database

use cypherlite::{Database, Value};
use cypherlite_storage::{adopt_native_default_wal, reset_uri};
use std::path::Path;

fn main() -> cypherlite::Result<()> {
    if let Some(path) = std::env::args_os().nth(1) {
        // Operator must have verified that this physical direct wal/ belongs
        // to this root and that both owners are closed. Format cannot prove it.
        adopt_native_default_wal(Path::new(&path))?;
        println!("adopted default WAL at {}", Path::new(&path).display());
        return Ok(());
    }

    let directory = tempfile::tempdir().expect("temporary parent");
    let root = directory.path().join("legacy");
    let uri = root.to_str().expect("UTF-8 temporary path");
    // These files were generated by the origin/main writer before ADR-0097;
    // Ada is checkpointed at LSN 1, Bob exists only in the WAL at LSN 2.
    let manifest = include_bytes!(
        "../../cypherlite-storage/tests/fixtures/pre_adr0084_default_wal/manifest.json"
    );
    let graph = include_bytes!(
        "../../cypherlite-storage/tests/fixtures/pre_adr0084_default_wal/graph.json"
    );
    let frames = include_bytes!(
        "../../cypherlite-storage/tests/fixtures/pre_adr0084_default_wal/wal/00000001.log"
    );
    std::fs::create_dir_all(root.join("wal"))?;
    std::fs::write(root.join("manifest.json"), manifest)?;
    std::fs::write(root.join("graph.json"), graph)?;
    let wal_path = root.join("wal/00000001.log");
    std::fs::write(&wal_path, frames)?;
    assert!(!root.join(cypherlite_storage::LOCK_MARKER).exists());
    assert!(!root
        .join("wal")
        .join(cypherlite_storage::LOCK_MARKER)
        .exists());
    assert!(Database::open(uri).is_err());
    assert!(reset_uri(uri, None).is_err());

    // The fixture's known origin establishes ownership. For a real store,
    // the operator must independently verify it before asserting adoption.
    adopt_native_default_wal(&root)?;
    let reopened = Database::open(uri)?;
    let rows = reopened
        .connect()?
        .query("MATCH (n:Person) RETURN n.name, n.age ORDER BY n.name")?;
    assert_eq!(rows.header.columns, ["n.name", "n.age"]);
    assert_eq!(
        rows.rows,
        vec![
            vec![Value::String("Ada".into()), Value::Int(37)],
            vec![Value::String("Bob".into()), Value::Int(42)],
        ]
    );
    // ADR-0127 migrate-on-open: the fixture's graph.json has no
    // `value_encoding` marker, so it classifies as legacy (encoding 1) and
    // the open above migrated the store in place — legacy-reader load, WAL
    // replay, checkpoint at the current format, WAL rotation — before
    // serving the query. Assert the migrated markers, not the pre-ADR-0127
    // "open never mutates" byte identity.
    let graph_after: serde_json::Value =
        serde_json::from_slice(&std::fs::read(root.join("graph.json"))?)
            .expect("migrated graph.json parses");
    assert_eq!(
        graph_after["value_encoding"], 2,
        "open migrated the legacy (value_encoding-1) snapshot"
    );
    let manifest_after: serde_json::Value =
        serde_json::from_slice(&std::fs::read(root.join("manifest.json"))?)
            .expect("migrated manifest.json parses");
    assert!(
        manifest_after["checkpoint_lsn"]
            .as_u64()
            .expect("checkpoint_lsn is an integer")
            >= 2,
        "migration checkpoint covers the WAL tail at LSN 2: {manifest_after}"
    );
    // The WAL rotated to a fresh active segment: the legacy segment's
    // records are checkpointed and the segment recycled.
    assert!(!wal_path.exists(), "legacy segment recycled: {wal_path:?}");
    let mut segments: Vec<String> = std::fs::read_dir(root.join("wal"))?
        .map(|entry| {
            entry
                .expect("wal entry")
                .file_name()
                .to_string_lossy()
                .into_owned()
        })
        .filter(|name| name.ends_with(".log"))
        .collect();
    segments.sort();
    assert_eq!(
        segments,
        ["00000002.log"],
        "WAL rotated to a single fresh active segment"
    );
    assert_ne!(
        std::fs::read(root.join("wal/00000002.log"))?,
        frames,
        "fresh segment does not carry the legacy fixture bytes"
    );
    drop(reopened); // Normal close checkpoints the recovered graph.
    reset_uri(uri, None)?;
    assert!(!root.exists());
    Ok(())
}
